// People placed in the world (S1a, T5, T7, T4, G6, T6, G8, T8, L4). Tile coordinates; face 0 down, 2 right, 4 up, 6 left. Every line grounded in the bible (Goldacre, Salt Bay, Pinegrove, Spindlewood, Routes 3, 5, 7, 8, 9, 10, 111) or plain greeting / weather flavour. A Skill teacher has script 'teach', skill, lines (the offer) and known (after).
// { id, x, y, sprite (TRAINER_OW8 key), face, move: 'still' | 'wander' | 'path', path?: [[x, y], ...], r?: wander radius in tiles, name?, lines: [page, ...], trainer?: { cls, name, team: [[species, rel]], sight, money, say, lose } }
// A trainer team scales with the challenger's badges: level = route cap-5 + rel (rel 0..3, see ADVN.range), the first N entries by band size, species evolved to match. money = payout per level of the strongest mon.
window.ADV_NPCS = [
  // ---------- Goldacre: villagers ----------
  { id: 'g7-granny', x: 236, y: 704, sprite: 'npc3-old-woman-cane', face: 0, move: 'still', lines: ['Miss Whitney came all the way from Johto, dear. She named our town after her old one, Goldenrod.', 'She still frets about a boy back home. Her Miltank rolled over him one whole afternoon!'] },
  { id: 'g7-farmer', x: 240, y: 715, sprite: 'npc3-bearded-man', face: 0, move: 'wander', r: 2, lines: ['No fences, no gates. Never needed \'em. Goldacre trusts folk, and folk have never let us down.', 'Want a Mareep or a Wooloo? Walk the fields round town. They\'ll come and find you.'] },
  { id: 'g7-kid', x: 259, y: 708, sprite: 'npc2-red-shirt-boy', face: 4, move: 'wander', r: 3, lines: ['That big red barn is the gym! Miss Whitney\'s Miltank rolls around SO fast. Like a boulder!', 'I\'m going to beat it one day. I practise dodging every morning. Mostly my sister\'s pillow.'] },
  { id: 'g7-woman', x: 232, y: 709, sprite: 'npc3-apron-woman', face: 0, move: 'wander', r: 3, lines: ['Someone really ought to organise a harvest festival. We certainly have the harvest for it.', 'I\'ve made a list of who that someone should be. It\'s mostly my sister.'] },
  { id: 'g7-turbine', x: 227, y: 722, sprite: 'npc2-jumpsuit-man', face: 2, move: 'still', lines: ['See the turbines on the ridge? That\'s Route 7, south of town. Follow them down to Longshore.', 'They make all of Goldacre\'s power, and we sell what\'s left. The wind never asks for a day off.'] },
  { id: 'g7-youngster', x: 231, y: 688, sprite: 'npc1-blue-haired-boy', face: 0, move: 'wander', r: 3, lines: ['Heading down Route 7? Go by day. Houndour come down onto the open pasture at night.', 'Unless you WANT a Houndour. Then go at night, and take plenty of Potions.'] },
  { id: 'g7-bibarel', x: 209, y: 708, sprite: 'fishing', face: 6, move: 'still', lines: ['Bidoof dam the river up on Route 8, north of town. The ford wanders, so we built a bridge.', 'Want to fish? Follow Route 8 to the shore road. The fishermen out there will teach anyone.'] },
  { id: 'g7-delivery', x: 243, y: 719, sprite: 'delivery', face: 4, move: 'wander', r: 2, lines: ['In season the vans run down to Longshore every day. Milk, cabbages, berries, the lot.', 'Half of Kenora eats what Goldacre grows. The other half buys it in Tradeway for twice the price.'] },
  { id: 'g7-cowgirl', x: 256, y: 691, sprite: 'cowgirl', face: 0, move: 'wander', r: 2, lines: ['Wild Miltank graze along Route 5, east of town. Miss Whitney picked her ace out of a field there.', 'If you meet one, be polite. Miltank never forget a face.'] },
  { id: 'g7-cherubi', x: 251, y: 721, sprite: 'npc3-cap-girl', face: 4, move: 'wander', r: 3, lines: ['Cherubi hide in our crop fields, just like the Cherimart mascot! Look between the rows.', 'I caught one yesterday. It smells like fruit salad. I love it.'] },
  { id: 'g7-sky', x: 222, y: 711, sprite: 'npc3-apron-woman', face: 0, move: 'wander', r: 3, lines: ['What a lot of sky today. I never get tired of it.', 'My sister wants me to run a harvest festival. I\'d rather lie in the hay and count clouds.'] },

  // ---------- Route 5: the open fields (youngsters, lasses) ----------
  { id: 'r5-cal', x: 287, y: 653, sprite: 'npc2-red-shirt-boy', face: 0, move: 'still', lines: ['Route 5 runs east to Tradeway. Battle everyone on the way and you\'ll be ready for Miss Whitney.'],
    trainer: { cls: 'Youngster', name: 'Cal', sight: 5, money: 16, team: [['wooloo', 0], ['bunnelby', 1], ['wooloo', 1], ['bunnelby', 2], ['wooloo', 3], ['bunnelby', 3]], say: 'Hey! Route 5 is the safest road in Kenora. Perfect for a warm-up battle!', lose: 'Whoa, you\'re strong! I need a longer warm-up.' } },
  { id: 'r5-jenna', x: 292, y: 663, sprite: 'npc4-ponytail-girl', face: 6, move: 'still', lines: ['Wild Miltank graze in the fields past the hedges. I\'ve been trying to catch one all week.'],
    trainer: { cls: 'Lass', name: 'Jenna', sight: 5, money: 24, team: [['bunnelby', 0], ['combee', 1], ['wooloo', 1], ['nickit', 2], ['combee', 2], ['wooloo', 3]], say: 'Hedges on both sides of the road. You can\'t sneak past me!', lose: 'Oh no, I lost! And now my hair\'s full of hedge.' } },
  { id: 'r5-dee', x: 309, y: 658, sprite: 'npc3-cap-girl', face: 2, move: 'still', lines: ['My Miltank came from a field on this road. She\'s the gentlest one in Kenora, I promise.'],
    trainer: { cls: 'Picnicker', name: 'Dee', sight: 5, money: 24, team: [['wooloo', 0], ['miltank', 1], ['bunnelby', 2], ['miltank', 2], ['wooloo', 3], ['miltank', 3]], say: 'The fields are lovely today. Let\'s battle, then have a picnic!', lose: 'That was fun! You win. You\'re still not getting my sandwiches.' } },
  { id: 'r5-ned', x: 311, y: 660, sprite: 'npc4-brown-haired-boy', face: 4, move: 'still', lines: ['Slip through a gap in the hedge and you\'ll find Bunnelby digging in the fields. Wooloo too.'],
    trainer: { cls: 'Youngster', name: 'Ned', sight: 5, money: 16, team: [['bunnelby', 0], ['wooloo', 1], ['bouffalant', 2], ['bunnelby', 2], ['tepig', 3], ['bouffalant', 3]], say: 'You can see forever from this road. And I can see you!', lose: 'I should have hidden behind a hedge.' } },

  // ---------- Route 21: the Eastern Ridge (map-lab pilot 3; hikers on the roads below the massifs, a hut keeper). Flavour lines only. ----------
  { id: 'r21-hut', x: 675, y: 344, sprite: 'npc5-camo-man', face: 0, move: 'still', lines: ['Quiet up here. The wind off the ridge keeps my hut cool all summer, and freezing all winter.', 'Aron chew the rocks by the stairs at dawn. A Fighting or Water type makes short work of them.'] },
  { id: 'r21-tor', x: 669, y: 352, sprite: 'npc1-explorer', face: 2, move: 'still', lines: ['I climb both massifs every morning. The west one has the better view. The east one, better snacks.'],
    trainer: { cls: 'Hiker', name: 'Tor', sight: 4, money: 24, team: [['aron', 0], ['nacli', 1], ['aron', 1], ['rockruff', 2], ['nacli', 2], ['cufant', 3]], say: 'Legs warmed up? Mine are! Let\'s battle!', lose: 'Oof. The ridge was easier than you.' } },
  { id: 'r21-kai', x: 674, y: 359, sprite: 'north-headband-brawler', face: 6, move: 'still', lines: ['Up the stairs, down the stairs. The Hawlucha watch me train at night. I think they\'re judging me.'],
    trainer: { cls: 'Black Belt', name: 'Kai', sight: 4, money: 24, team: [['nickit', 0], ['rockruff', 1], ['nickit', 1], ['hawlucha', 2], ['rockruff', 2], ['hawlucha', 3]], say: 'Hyah! Show me your strength!', lose: 'Hngh. A thousand more steps for me tonight.' } },
  { id: 'r21-wren', x: 658, y: 361, sprite: 'npc4-ponytail-girl', face: 0, move: 'still', lines: ['There\'s a cave in the east cliff. I\'m not going in without a light. Or a friend. Or two friends.'],
    trainer: { cls: 'Picnicker', name: 'Wren', sight: 4, money: 20, team: [['nickit', 0], ['aron', 1], ['nacli', 1], ['nickit', 2], ['aron', 2], ['cufant', 3]], say: 'You came down the road? Then you have to battle me! Those are the rules!', lose: 'Aww. Good battle, though. I made up those rules anyway.' } },

  // ---------- Route 22: the orchard road (map-lab pilot 1; villagers). Flavour lines only. ----------
  { id: 'r22-keeper', x: 701, y: 399, sprite: 'npc3-apron-woman', face: 6, move: 'still', lines: ['The orchard wants picking every few days in season. My back knows it, and it complains.', 'Leave the Combee be in the blossom. They\'re the reason the fruit comes in so sweet.'] },
  { id: 'r22-bench', x: 695, y: 402, sprite: 'npc2-old-man', face: 2, move: 'still', lines: ['I sit by the orchard gate. Nothing much happens, and that suits me down to the ground.', 'Come back after dark. Volbeat and Illumise dance over the trees. Best show in Kenora, and free.'] },
  { id: 'r22-walker', x: 675, y: 385, sprite: 'npc1-explorer', face: 6, move: 'still', lines: ['There\'s an old ruined gate out in the west meadow. Nobody knows who built it, or what it kept out.'] },
  { id: 'r22-kid', x: 682, y: 388, sprite: 'npc4-vest-boy', face: 0, move: 'wander', r: 2, lines: ['I\'m looking for Combee. They like the flowers by the road. Ow! Found one.'] },
  { id: 'r22-stall', x: 698, y: 401, sprite: 'npc1-red-cap-man', face: 0, move: 'still', lines: ['Fresh off the trees this morning! Best fruit on the whole road.', 'Aldermere folk pay double for it, and they still try to haggle.'] },
  { id: 'r22-pond', x: 697, y: 405, sprite: 'npc4-ponytail-girl', face: 2, move: 'still', lines: ['The pond\'s so still today you can see every cloud in it. Then I sneeze and ruin it.'] },

  // ---------- Route 7: the grazing country (ranchers, hikers) ----------
  { id: 'r7-walt', x: 180, y: 752, sprite: 'npc2-bearded-man', face: 0, move: 'still', lines: ['Mareep wool comes in fluffiest after a windy night. All that static, see. Ask the turbines.'],
    trainer: { cls: 'Rancher', name: 'Walt', sight: 5, money: 24, team: [['mareep', 0], ['mareep', 1], ['smoliv', 1], ['mareep', 2], ['smoliv', 2], ['mareep', 3]], say: 'Stock grazes all over Route 7. Mind you don\'t spook my Mareep!', lose: 'Fair fight. Your team\'s got grit, I\'ll give you that.' } },
  { id: 'r7-gus', x: 199, y: 762, sprite: 'npc1-explorer', face: 6, move: 'still', script: 'coach', skill: 'rough', name: 'Gus', time: 22, course: [[186, 751], [192, 752], [199, 755], [201, 758]], coach: ['Rough ground suits a heavy mount, like a Tauros. I can teach you to ride one over it.', 'Pay me, take the hard lesson, or ride my course against the clock.'], known: ['You ride rough ground well. Keep a heavy mount for the rocky bits.'], lines: ['Houndour come down onto the pasture at night. I wouldn\'t camp out here.'],
    trainer: { cls: 'Hiker', name: 'Gus', sight: 5, money: 24, team: [['rockruff', 0], ['mankey', 1], ['rockruff', 1], ['mankey', 2], ['rockruff', 2], ['mankey', 3]], say: 'The ground gets rough up here. Good country for a hiker!', lose: 'My legs are stronger than my Pokemon. Hm. Noted.' } },
  { id: 'r7-dolly', x: 218, y: 755, sprite: 'cowgirl', face: 0, move: 'still', script: 'coach', skill: 'canter', name: 'Dolly', time: 32, course: [[223, 754], [218, 760], [207, 760], [202, 752], [198, 742], [210, 742]], coach: ['Open grazing land like this is made for a canter. Got a Ponyta? I can teach you.', 'Pay up, try the hard lesson, or race my course against the clock. Your call!'], known: ['You canter like you were born to it. The open land is yours.'], lines: ['You can hear the turbines the whole way along this road. Whum, whum, whum.'],
    trainer: { cls: 'Rancher', name: 'Dolly', sight: 5, money: 24, team: [['mareep', 0], ['smoliv', 1], ['mareep', 1], ['seviper', 2], ['smoliv', 2], ['mareep', 3]], say: 'Wide open land. Nowhere to hide, is there, partner?', lose: 'Whoa there! You rode me right out of the saddle!' } },
  { id: 'r7-ike', x: 240, y: 765, sprite: 'npc1-explorer', face: 2, move: 'still', script: 'coach', skill: 'boulder', name: 'Ike', time: 24, course: [[227, 757], [226, 749], [234, 749], [238, 751]], coach: ['The edges of this road are all hills and rocks. I can teach you to ride a climber up them.', 'Pay me, take the hard lesson, or ride my course against the clock.'], known: ['You ride the rocks well. Keep at it.'], lines: ['Route 7 is rougher than Route 5. Little hills, loose rocks, and Rockruff at night.'],
    trainer: { cls: 'Hiker', name: 'Ike', sight: 5, money: 24, team: [['mankey', 0], ['rockruff', 1], ['houndour', 1], ['mankey', 2], ['houndour', 2], ['rockruff', 3]], say: 'Hear that whirring? The turbines are cheering us on.', lose: 'Whew. You wore me out. Even the turbines stopped to watch.' } },

  // ---------- Route 8: the river bottom (farmers, fishermen) ----------
  { id: 'r8-abel', x: 228, y: 655, sprite: 'npc3-old-man-cane', face: 4, move: 'still', lines: ['Bibarel keep shifting the water. The ford\'s fine one day and gone the next. Use the bridge.'],
    trainer: { cls: 'Farmer', name: 'Abel', sight: 5, money: 20, team: [['bidoof', 0], ['wooper', 1], ['bidoof', 1], ['marill', 2], ['wooper', 2], ['bidoof', 3]], say: 'These water meadows are wet underfoot. The Bidoof see to that!', lose: 'Wet and beaten. That\'s me every spring.' } },
  { id: 'r8-dale', x: 228, y: 649, sprite: 'fishing', face: 0, move: 'still', lines: ['Totodile live in this river. I saw one once. Or it was a log. A very toothy log.'],
    trainer: { cls: 'Fisherman', name: 'Dale', sight: 5, money: 20, team: [['krabby', 0], ['staryu', 1], ['krabby', 1], ['mareanie', 2], ['staryu', 2], ['mareanie', 3]], say: 'Shh! You\'ll scare the fish! Oh, fine. Let\'s battle.', lose: 'And now the fish are laughing at me.' } },
  { id: 'r8-wes', x: 224, y: 653, sprite: 'fishing2', face: 6, move: 'still', lines: ['Psyduck and Buizel come out after dark. You hear them before you see them. Mostly quacking.'],
    trainer: { cls: 'Fisherman', name: 'Wes', sight: 5, money: 20, team: [['psyduck', 0], ['buizel', 1], ['krabby', 1], ['palpitoad', 2], ['buizel', 2], ['totodile', 3]], say: 'I\'m waiting on a bite. A battle will pass the time!', lose: 'Reel me in. I\'m done.' } },
  { id: 'r8-boyd', x: 236, y: 654, sprite: 'npc2-striped-shirt-man', face: 6, move: 'still', lines: ['Follow this road north to the shore road, then west for Salt Bay. They teach fishing out there.'],
    trainer: { cls: 'Farmer', name: 'Boyd', sight: 5, money: 20, team: [['wooper', 0], ['bidoof', 1], ['marill', 1], ['wooper', 2], ['marill', 2], ['bidoof', 3]], say: 'My meadows are soaked all year. Good thing Bidoof love it!', lose: 'Soaked and beaten. Double soggy.' } },
  { id: 'r8-gil', x: 228, y: 650, sprite: 'npc1-green-shirt-man', face: 0, move: 'still', lines: ['Willow trees all along here. Best shade on the river road for a nap after a battle.'],
    trainer: { cls: 'Rancher', name: 'Gil', sight: 5, money: 24, team: [['marill', 0], ['bidoof', 1], ['buizel', 1], ['grookey', 2], ['marill', 2], ['wooper', 3]], say: 'A trainer on the river road! Let\'s go!', lose: 'You\'ve got a strong team. Stronger than the current, even.' } },
  // ---------- Salt Bay: the fishing village (two Skill teachers on the piers, villagers) ----------
  { id: 's5-surf', x: 78, y: 634, sprite: 'npc4-sailor', face: 6, move: 'still', script: 'teach', skill: 'surf', name: 'Surf teacher', lines: ['Twenty metres out the ground is simply gone. That is why we teach surfing properly.', 'Mind the deep water. Do you want to learn how to cross it?'], known: ['You know how now. Keep a calm head out there, the bay has no bottom.'] },
  { id: 's5-fish', x: 80, y: 642, sprite: 'fishing2', face: 6, move: 'still', script: 'teach', skill: 'fishing', name: 'Fishing teacher', lines: ['Four generations of my family have done nothing but fish. Fancy being the fifth?', 'Here\'s a rod. Sit still, face the water, and be patient.'], known: ['The rod is yours. Face the water, press F to cast, and wait. Patience is the bait.'] },
  { id: 's5-measure', x: 98, y: 627, sprite: 'npc2-striped-shirt-man', face: 0, move: 'wander', r: 2, lines: ['Someone tried to measure the bay once. Tied a rope to a rock, let it down, ran out of rope.', 'Everyone here tells it differently. I tell it best. Nobody has tried since, mind.'] },
  { id: 's5-feebas', x: 126, y: 644, sprite: 'fishing', face: 0, move: 'wander', r: 2, lines: ['Feebas is our legend. Every fisherman here has a secret spot, and every one of them is wrong.', 'Mine\'s the right one, of course. No, I won\'t tell you where.'] },
  { id: 's5-net', x: 100, y: 618, sprite: 'npc2-purple-top-woman', face: 0, move: 'wander', r: 2, lines: ['Nets, boats, racks. That is Salt Bay. We are not struggling, we have what we need.', 'Odd thing, though. Fewer Wingull on the racks this spring. Gulls don\'t just stop coming.'] },
  { id: 's5-kid', x: 102, y: 640, sprite: 'npc2-yellow-shirt-boy', face: 0, move: 'wander', r: 1, lines: ['The road ends at the water. People only come here on purpose, or by mistake. Which are you?'] },
  { id: 's5-night', x: 78, y: 637, sprite: 'npc3-old-woman-cane', face: 6, move: 'still', lines: ['At night something glows under the water. Lanturn and Chinchou, lit up from below.', 'When I was small I thought the stars had fallen in. I still like that better.'] },
  { id: 's5-quiet', x: 115, y: 644, sprite: 'npc1-red-cap-man', face: 0, move: 'wander', r: 2, lines: ['The catch is thin. Deep cold water holds little, so we take what comes.', 'Skrelp and Remoraid bite off the piers if you\'ve got a rod and the patience.'] },

  // ---------- Route 9: the working shore (nets, boats, drying racks; a stranger teaches fishing before you reach town) ----------
  { id: 'r9-teacher', x: 161, y: 641, sprite: 'npc5-old-man', face: 0, move: 'still', script: 'teach', skill: 'fishing', name: 'Fisherman', lines: ['Everyone on this road fishes, and we like to teach. Do you want to learn?', 'Take this rod. Cast it at the water and wait.'], known: ['Face the water and press F to cast. People are fishing the whole length of this road.'] },
  { id: 'r9-hal', x: 154, y: 632, sprite: 'fishing', face: 0, move: 'still', lines: ['Nets, racks, boats. This is a working shore, not a holiday. Longshore\'s the holiday.'],
    trainer: { cls: 'Fisherman', name: 'Hal', avatar: 'fisherman', sight: 5, money: 20, team: [['magikarp',0],['wimpod',1],['krabby',1],['carvanha',2],['chinchou',2],['marill',3]], say: 'I\'ve fished this shore all my life. Let me show you what bites!', lose: 'The big one got away again. It always does.' } },
  { id: 'r9-moss', x: 171, y: 640, sprite: 'npc4-sailor', face: 4, move: 'still', lines: ['Salt Bay is just west of here. Last stop on the road, unless you can surf.'],
    trainer: { cls: 'Sailor', name: 'Moss', avatar: 'sailor', sight: 5, money: 20, team: [['wingull',0],['wimpod',1],['wingull',1],['carvanha',2],['wimpod',2],['carvanha',3]], say: 'Salt Bay\'s a working shore. No tourists, no kiosks, just us!', lose: 'Overboard I go!' } },
  { id: 'r9-finn', x: 179, y: 630, sprite: 'fishing2', face: 0, move: 'still', lines: ['Mind the nets on the bank. They are mending, not decoration.'],
    trainer: { cls: 'Fisherman', name: 'Finn', avatar: 'fisherman', sight: 5, money: 20, team: [['magikarp',0],['marill',1],['magikarp',1],['krabby',2],['chinchou',2],['mudkip',3]], say: 'The drying racks do not fill themselves. Battle first, chat after!', lose: 'You reeled me in.' } },
  { id: 'r9-pru', x: 188, y: 638, sprite: 'npc4-sailor', face: 4, move: 'still', lines: ['Carvanha bite at night. Not the line. The boots. Wear thick boots.'],
    trainer: { cls: 'Sailor', name: 'Pru', avatar: 'sailor', sight: 5, money: 20, team: [['marill',0],['wingull',1],['wimpod',1],['krabby',2],['carvanha',2],['chinchou',3]], say: 'Boats, nets, racks. We\'ve got everything but visitors!', lose: 'Fair winds to you, and a full net.' } },

  // ---------- Route 10: the lakeside (the campsite and its register; Nickit and Purrloin own the night) ----------
  { id: 'r10-register', x: 210, y: 568, sprite: null, face: 0, move: 'still', name: 'Campsite register', lines: ['The campsite register. There are three other names in it.', 'You sign your own name below theirs.'] },
  { id: 'r10-gossip', x: 214, y: 565, sprite: 'npc1-backwards-cap-boy', face: 0, move: 'still', lines: ['A trainer came through last week. Tall, I think. Or maybe short. Definitely wearing shoes.', 'Anyway, they signed the register like everyone else. Everyone does.'] },
  { id: 'r10-owen', x: 202, y: 613, sprite: 'npc1-headband-boy', face: 2, move: 'still', lines: ['Sign the register at the campsite. Everyone does, it is only polite.'],
    trainer: { cls: 'Camper', name: 'Owen', avatar: 'camper', sight: 5, money: 16, team: [['ducklett',0],['skiddo',1],['nickit',1],['purrloin',2],['pikachu',2],['ducklett',3]], say: 'I pitched my tent this morning. Fancy a battle before supper?', lose: 'Supper time already? I\'ve lost my appetite. No, wait, it\'s back.' } },
  { id: 'r10-mara', x: 211, y: 600, sprite: 'npc1-ponytail-girl', face: 6, move: 'still', lines: ['Shore Pokemon at one end of this road, lake Pokemon at the other. Pikachu in between!'],
    trainer: { cls: 'Picnicker', name: 'Mara', avatar: 'picnicker', sight: 5, money: 24, team: [['ducklett',0],['skiddo',1],['lotad',1],['marill',2],['pikachu',2],['bulbasaur',3]], say: 'The lake is lovely out here. Salt at one end, fresh at the other!', lose: 'Oh well. Back to my picnic. Salt or fresh, a sandwich is a sandwich.' } },
  { id: 'r10-reed', x: 203, y: 586, sprite: 'fishing', face: 2, move: 'still', lines: ['Salt Bay folk chase Feebas their whole lives. I swear I saw one in this lake after dark.'],
    trainer: { cls: 'Fisherman', name: 'Reed', avatar: 'fisherman', sight: 5, money: 20, team: [['magikarp',0],['lotad',1],['marill',1],['piplup',2],['magikarp',2],['marill',3]], say: 'Nothing\'s biting, so you\'ll do.', lose: 'Not a nibble all day. Story of my life.' } },
  { id: 'r10-pip', x: 210, y: 578, sprite: 'npc1-headband-boy', face: 6, move: 'still', lines: ['Nickit took my map last night. Then a Purrloin took the Nickit\'s dinner. Fair\'s fair.'],
    trainer: { cls: 'Camper', name: 'Pip', avatar: 'camper', sight: 5, money: 16, team: [['nickit',0],['purrloin',1],['ducklett',1],['skiddo',2],['nickit',2],['purrloin',3]], say: 'Nickit and Purrloin come out at night. I keep an eye on my bag!', lose: 'Mind my bag while I recover, would you?' } },

  // ---------- Longshore: the beach resort (ice cream, a lifeguard, hire kiosks; the Sandygast castles and the dock are up the coast on the Route 6 strip) ----------
  { id: 't7-ice', x: 106, y: 765, sprite: 'shopm2', face: 4, move: 'still', lines: ['Ice cream! Best job in Kenora, and I wouldn\'t swap it for a gym badge.', 'Everything on this boardwalk comes down from the Goldacre farms. Even the milk in the cones.'] },
  { id: 't7-guard', x: 90, y: 772, sprite: 'sportsman', face: 6, move: 'still', lines: ['Past the buoys is Sharpedo water. Everyone ignores the signs.', 'Nothing\'s ever happened, so nobody listens. I blow my whistle anyway. It\'s a very good whistle.'] },
  { id: 't7-kid', x: 86, y: 764, sprite: 'npc1-backwards-cap-boy', face: 6, move: 'wander', r: 2, lines: ['The water only comes up to my chest, even way out past the buoys!', 'Mum says that is far enough. I say it is not.'] },
  { id: 't7-hire', x: 93, y: 776, sprite: 'npc3-pikachu-kid', face: 4, move: 'still', script: 'class', skill: 'surf', name: 'Board hire', fee: 800, lines: ['Hire a board and ride it badly. Everybody shouts. It\'s great fun.', 'I can show you the basics of surfing. Want a lesson?'], known: ['You can stay on a board now! Salt Bay folk teach it properly. We teach it loudly.'] },
  { id: 't7-van', x: 101, y: 762, sprite: 'delivery', face: 0, move: 'wander', r: 1, lines: ['Vans down from Goldacre all summer. Fruit, veg, milk, the lot.', 'Goldacre\'s east of here. Take Route 6 out of town and mind the sandcastles on the way.'] },
  { id: 't7-gran', x: 98, y: 769, sprite: 'npc3-old-woman-cane', face: 6, move: 'still', lines: ['In winter half this town boards up. It\'s a very different place then.', 'Quieter. Just me, the gulls and the sea. Don\'t tell the tourists, but I like it best.'] },
  { id: 't7-chips', x: 98, y: 779, sprite: 'npc4-bowler-hat-man', face: 6, move: 'wander', r: 1, lines: ['A Wingull stole my chips again! They steal from everyone on the boardwalk.', 'Now I buy two portions. One for me, one for the Wingull. It saves time.'] },
  { id: 't7-pika', x: 103, y: 770, sprite: 'npc4-ponytail-girl', face: 0, move: 'wander', r: 1, lines: ['A Pikachu and a Meowth hang around the boardwalk. Nobody minds.', 'There\'s a grey Meowth too, asleep on a man asleep on the bench. They\'ve been there since lunch.'] },
  { id: 't7-blowout', x: 112, y: 764, sprite: 'npc2-bearded-man', face: 6, move: 'still', lines: ['Sprucevale runs a Big Summer Blowout. Its big boss spends the season here, I hear.'] },
  { id: 't7-tourist', x: 96, y: 752, sprite: 'npc2-red-jacket-woman', face: 6, move: 'wander', r: 2, lines: ['Wide beach, boardwalk, ice cream and a little sunburn. Perfect.', 'A nice lady with a clipboard asked if my Pokemon ever gets scared. On holiday! Who asks that?'] },

  // ---------- Tradeway: the crossroads market at the cave mouth (independent trade, cash and no questions; the stalls run on into the Route 4 cave) ----------
  { id: 't4-trader', x: 387, y: 617, sprite: 'npc4-bowler-hat-man', face: 6, move: 'wander', r: 2, lines: ['Every Cherimart in Kenora sells the same shelf. Here the shelf changes by the day!', 'Today\'s special is whatever I\'ve got. Tomorrow\'s is something else. Come back often!'] },
  { id: 't4-grower', x: 391, y: 617, sprite: 'npc3-bearded-man', face: 4, move: 'still', lines: ['I bring my crates in by the orchard cut. Cash on the nail, no questions.'] },
  { id: 't4-nick', x: 388, y: 622, sprite: 'npc2-green-shirt-kid', face: 0, move: 'wander', r: 2, lines: ['Watch for Nickit and Purrloin. They work the stalls better than the traders do.', 'Want one of your own? Hang about the stalls. They\'ll find you before you find them.'] },
  { id: 't4-cross', x: 355, y: 618, sprite: 'npc3-white-haired-man', face: 2, move: 'still', lines: ['Every road in Kenora meets here. Dead centre of the region, give or take a stall.', 'West is Route 5 to Goldacre. The cave mouth is Route 4, and the road runs right on through.'] },
  { id: 't4-freight', x: 368, y: 617, sprite: 'npc3-bearded-man', face: 6, move: 'still', lines: ['The freight run to Aldermere leaves from here. Every Cherimart shelf starts on it.'] },
  { id: 't4-timber', x: 344, y: 618, sprite: 'npc2-jumpsuit-man', face: 2, move: 'wander', r: 1, lines: ['Pinegrove timber stacks up at this end of the road. Tools and supplies go back down.'] },
  { id: 't4-claystone', x: 374, y: 618, sprite: 'npc2-pink-suit-man', face: 0, move: 'still', lines: ['Claystone sends its finds down the spoil road. They sell here first, and cheap.'] },
  { id: 't4-mouth', x: 393, y: 617, sprite: 'npc4-vest-boy', face: 2, move: 'wander', r: 1, lines: ['The first stalls stood in the cave mouth, in the shade. Now they go a long way in.', 'Past the stalls the cave keeps going. Hikers train in there, so bring your best.'] },
  { id: 't4-scarf', x: 350, y: 618, sprite: 'npc1-striped-dress-girl', face: 0, move: 'wander', r: 2, lines: ['Purrloin took my scarf at the stalls. I bought it back from the stall next door.', 'Full price, too. I\'m not even cross. It\'s a very nice scarf.'] },
  { id: 't4-dark', x: 380, y: 628, sprite: 'npc2-purple-top-woman', face: 4, move: 'still', lines: ['Past the last stall the road gets dark. I stop at the last stall.'] },
  { id: 't4-cash', x: 359, y: 607, sprite: 'npc3-old-woman-cane', face: 0, move: 'still', lines: ['Cash is cash in Tradeway. Nobody asks who earned it.', 'A big fellow in a headband was asking who had a frightened Pokemon to sell. Even I said no.'] },

  // ---------- Sailsport and Aldermere City: the supply path between them (docs/TRAVEL.md): a paid supply mount, works on the path only; each handler stands where the town meets the freight run, Sailsport's at the shore ----------
  { id: 't2-ride', x: 713, y: 556, sprite: 'npc4-sailor', face: 0, move: 'still', script: 'rent', name: 'Freight crew', lines: ['Freight goes up to Aldermere City every day along the supply path.', 'A supply mount is for hire. It stays on the path, and goes home if you leave it.'] },
  { id: 'g5-ride', x: 697, y: 474, sprite: 'delivery', face: 0, move: 'still', script: 'rent', name: 'Freight crew', lines: ['Everything Sailsport ships ends up here, and the supply path is how it arrives.', 'A supply mount is for hire. It stays on the path, and goes home if you leave it.'] },

  // ---------- Classes (docs/TRAVEL.md): a town teacher takes money and sets the easy lesson (a bar with a moving marker). Each skill is taught in at least two places: here and on a route (the trainers on Routes 6 and 7 once beaten) ----------
  { id: 't2-rough', x: 712, y: 576, sprite: 'npc1-red-cap-man', face: 2, move: 'still', script: 'class', skill: 'rough', name: 'Horseshoe Freights hand', lines: ['Horseshoe Freights runs heavy stock over rock and scrub all week.', 'I teach rough riding to anyone who will put in the practice. Want a lesson?'], known: ['You have the knack. Keep a heavy mount for rocky ground.'] },
  { id: 't2-dune', x: 724, y: 573, sprite: 'npc4-vest-boy', face: 6, move: 'still', script: 'class', skill: 'dune', name: 'Coast guide', lines: ['The Route 24 coast is soft sand all the way. A good mount does not slow down in it.', 'I teach dune riding. Want a lesson?'], known: ['You have the knack. Sand will not slow your mount now.'] },
  { id: 'g5-canter', x: 682, y: 463, sprite: 'npc4-blonde-girl', face: 2, move: 'still', script: 'class', skill: 'canter', name: 'Riding mistress', lines: ['Fast mounts are Aldermere\'s pride. That and the museum, if you ask Professor Linden.', 'I teach cantering. Want a lesson?'], known: ['You have the knack. Open land and good roads are yours.'] },
  { id: 'g4-boulder', x: 394, y: 455, sprite: 'npc3-bearded-man', face: 2, move: 'still', script: 'class', skill: 'boulder', name: 'Quarry foreman', lines: ['Claystone is a quarry town. Our stone faces are climbed by the sure-footed, and nobody else.', 'I teach bouldering. Want a lesson?'], known: ['You have the knack. Climbers go where wheels cannot.'] },
  { id: 'g1-dune', x: 279, y: 280, sprite: 'npc1-explorer', face: 2, move: 'still', script: 'class', skill: 'dune', name: 'Desert guide', lines: ['Dunereach is all sand. You ride it or you wade it, all the way up the north road to the old tower.', 'I teach dune riding. Want a lesson?'], known: ['You have the knack. Sand won\'t slow your mount now. Not even on the north road.'] },
  { id: 'g2-snow', x: 607, y: 306, sprite: 'npc3-old-man-cane', face: 2, move: 'still', script: 'class', skill: 'snow', name: 'Snow guide', lines: ['Sprucevale snow comes up to your knees by midwinter. The right mount never slows in it.', 'I teach snow riding. Want a lesson?'], known: ['You have the knack. Deep snow will not slow your mount now.'] },
  { id: 't1-snow', x: 465, y: 309, sprite: 'npc1-backwards-cap-boy', face: 2, move: 'still', script: 'class', skill: 'snow', name: 'Snow guide', lines: ['Frostfall lives on its snow. We teach snow riding to anyone who asks.', 'Go on, ask. Want a lesson?'], known: ['You have the knack. Deep snow will not slow your mount now.'] },
  { id: 't1-fly', x: 435, y: 303, sprite: 'npc1-explorer', face: 6, move: 'still', script: 'class', skill: 'fly', name: 'Flight Hub instructor', fee: 2000, lines: ['This is the Flight Hub. We teach flying to trainers whose lead can learn Fly.', 'Want a lesson?'], known: ['You know how now. Press G to take off, and land on clear outdoor ground.'] },

  // ---------- Route 6: the seafront strip (the resort has spilled up the coast and taken the road; the dock and the castles; Lady, Sailor, Lass, Youngster) ----------
  { id: 'r6-dock', x: 84, y: 726, sprite: 'fishing2', face: 4, move: 'still', lines: ['Nothing out past the breakers is catchable from here. Shore and dock fishing only.', 'For the deep stuff, go to Salt Bay and learn to surf properly.'] },
  { id: 'r6-mum', x: 91, y: 727, sprite: 'npc3-apron-woman', face: 6, move: 'still', lines: ['Kids build sandcastles and wander off. Then the castles start dragging things under.', 'Those are Sandygast, dear. Keep well back, and keep hold of your bucket.'] },
  { id: 'r6-pearl', x: 136, y: 777, sprite: 'npc2-red-jacket-woman', face: 0, move: 'still', lines: ['Do mind my parasol. The sun here is simply relentless.'],
    trainer: { cls: 'Lady', name: 'Pearl', avatar: 'lady', sight: 5, money: 24, team: [['wingull', 0], ['krabby', 1], ['wingull', 1], ['sandygast', 2], ['krabby', 2], ['chinchou', 3]], say: 'The resort has crept all the way up the road. Care for a battle, dear?', lose: 'Oh dear. Pass me my sunscreen, and my dignity.' } },
  { id: 'r6-brine', x: 137, y: 783, sprite: 'npc4-sailor', face: 4, move: 'still', script: 'coach', skill: 'fly', name: 'Brine', coach: ['Gulls and winged Pokemon come in off the water here. I can teach you to fly with one.', 'Pay me, or take the hard lesson.'], known: ['You fly well. Keep an eye out for the gulls.'], lines: ['We put in at Longshore for the ice cream. Best reason there is to stop anywhere.'],
    trainer: { cls: 'Sailor', name: 'Brine', avatar: 'sailor', sight: 5, money: 20, team: [['wimpod', 0], ['wingull', 1], ['krabby', 1], ['wimpod', 2], ['chinchou', 2], ['wingull', 3]], say: 'Shore leave! Let\'s make it a quick battle.', lose: 'Back to my boat for me.' } },
  { id: 'r6-kit', x: 149, y: 773, sprite: 'npc2-pink-top-girl', face: 0, move: 'still', lines: ['I got sunburnt on day one. Totally worth it.'],
    trainer: { cls: 'Lass', name: 'Kit', avatar: 'lass', sight: 5, money: 24, team: [['krabby', 0], ['wingull', 1], ['sandygast', 1], ['wimpod', 2], ['krabby', 2], ['wingull', 3]], say: 'You\'re already on holiday, you know. Battle?', lose: 'My shoulders hurt, and now my pride does too.' } },
  { id: 'r6-tom', x: 159, y: 773, sprite: 'npc3-striped-boy', face: 0, move: 'still', lines: ['Mind the sandcastles. They are not always just sand.'],
    trainer: { cls: 'Youngster', name: 'Tom', avatar: 'youngster', sight: 5, money: 16, team: [['sandygast', 0], ['krabby', 1], ['sandygast', 1], ['wingull', 2], ['wimpod', 2], ['sandygast', 3]], say: 'Stay off the sandcastles! And take me on while you are here.', lose: 'My castle fell down too.' } },

  // ---------- Pinegrove: villagers (the logging town; every stand numbered, the mill never idle, the cold silence with Claystone) ----------
  { id: 'g6-feller', x: 490, y: 691, sprite: 'npc2-jumpsuit-man', face: 4, move: 'still', lines: ['Every log in that mill came off Route 3, north of town. I cut most of them myself.', 'My daughter plants two for every one I fell. She keeps count. Out loud. At dinner.'] },
  { id: 'g6-stands', x: 480, y: 690, sprite: 'npc2-purple-top-woman', face: 0, move: 'wander', r: 2, lines: ['Every stand has a number. You can read the whole rotation off the trees.', 'Bonsly hide among the saplings on Route 3. Look for the tree that blinks.'] },
  { id: 'g6-seedling', x: 471, y: 691, sprite: 'npc1-ponytail-girl', face: 2, move: 'wander', r: 3, lines: ['I water the seedlings south of town before school. Dad fells the trees, I plant them.', 'Two for every one he cuts. I\'m winning, by the way.'] },
  { id: 'g6-haul', x: 504, y: 691, sprite: 'delivery', face: 6, move: 'still', lines: ['Timber goes east on Route 111 to the Spindlewood docks. Tools and supplies come back the same way.'] },
  { id: 'g6-reader', x: 485, y: 681, sprite: 'npc5-old-man', face: 0, move: 'still', lines: ['Past the last house you can read the forest. Fresh cut, replanted, or left alone.', 'The left-alone stands are where Heracross live. Look up the trunks at night.'] },
  { id: 'g6-stump', x: 485, y: 700, sprite: 'npc2-red-shirt-boy', face: 4, move: 'wander', r: 3, lines: ['Keep clear of the old stumps after dark. That\'s all I\'ll say.', 'Okay, one more thing. Sometimes the stumps blink. THAT\'S all I\'ll say!'] },
  { id: 'g6-silence', x: 479, y: 696, sprite: 'npc1-green-shirt-man', face: 0, move: 'still', lines: ['Nobody here trades with Claystone. Nobody here says why, either.', 'My grandad might have known. He just went quiet and changed the subject. Everyone does.'] },
  { id: 'g6-kleavor', x: 469, y: 678, sprite: 'npc3-old-woman-cane', face: 0, move: 'still', lines: ['Aspen has the only Kleavor in Kenora. She earned it the long way, one stand at a time.'] },
  { id: 'g6-gymkid', x: 500, y: 686, sprite: 'npc5-striped-boy', face: 2, move: 'wander', r: 2, lines: ['That big mill is the gym! Aspen runs it herself.', 'Her crew\'s all bugs and big lifters. Dad says take a Fire type. Mum says take a packed lunch.'] },
  { id: 'g6-notice', x: 481, y: 694, sprite: 'npc1-green-shirt-man', face: 4, move: 'still', lines: ['The board lists every stand and its date. Felled, replanted, left alone.', 'Someone keeps writing \'spooky?\' next to stand forty. Nobody owns up to it.'] },

  // ---------- Route 3: the working forest (lumberjacks, a forester, a bug catcher and a picnicker among the numbered stands) ----------
  { id: 'r3-pike', x: 481, y: 621, sprite: 'npc1-red-cap-man', face: 2, move: 'still', lines: ['Every felled stand gets replanted. That\'s the rule here, and I keep it.'],
    trainer: { cls: 'Lumberjack', name: 'Pike', avatar: 'hiker', sight: 5, money: 24, team: [['bonsly',0],['machop',1],['bonsly',1],['seedot',2],['machop',2],['heracross',3]], say: 'This stand comes down today. Care to test your team against a lumberjack\'s?', lose: 'Clean cut. You stood like an old oak.' } },
  { id: 'r3-wren', x: 489, y: 626, sprite: 'npc1-headband-boy', face: 6, move: 'still', lines: ['The Burmy here wear bark. In town they wear sawdust. In my bag they wear my socks.'],
    trainer: { cls: 'Bug Catcher', name: 'Wren', avatar: 'bugcatcher', sight: 5, money: 16, team: [['burmy',0],['heracross',1],['burmy',1],['bonsly',2],['heracross',2],['burmy',3]], say: 'Burmy dress up in whatever\'s around. Want to see their outfits?', lose: 'My Burmy lost its cloak!' } },
  { id: 'r3-tuck', x: 481, y: 631, sprite: 'npc3-white-haired-man', face: 2, move: 'still', lines: ['Route 3 runs north to Hallowmead. Read the stand markers and you\'ll never get lost.'],
    trainer: { cls: 'Forester', name: 'Tuck', avatar: 'hiker', sight: 5, money: 24, team: [['seedot',0],['bonsly',1],['seedot',1],['chikorita',2],['machop',2],['seedot',3]], say: 'I replant what I fell. Let\'s see what you\'ve grown!', lose: 'Good roots. You\'ll go far.' } },
  { id: 'r3-sorrel', x: 490, y: 636, sprite: 'npc3-cap-girl', face: 6, move: 'still', lines: ['It\'s quiet out here once the saws stop. Then the Phantump start. I leave before dark.'],
    trainer: { cls: 'Picnicker', name: 'Sorrel', avatar: 'picnicker', sight: 5, money: 24, team: [['seedot',0],['burmy',1],['bonsly',1],['chikorita',2],['seedot',2],['bonsly',3]], say: 'Lunch among the stumps. They don\'t mind. Battle?', lose: 'Oh no, my sandwich!' } },

  // ---------- Route 111: the timber haul (landings, trucks and a loader; teamsters, a bug catcher, a fisherman, a hiker) ----------
  { id: 'r111-dale', x: 529, y: 687, sprite: 'npc3-bearded-man', face: 0, move: 'still', lines: ['Landings every few hundred metres. Load, haul, come back. Spindlewood\'s at the far end.'],
    trainer: { cls: 'Teamster', name: 'Dale', avatar: 'hiker', sight: 5, money: 24, team: [['timburr',0],['slowpoke',1],['timburr',1],['sewaddle',2],['slowpoke',2],['timburr',3]], say: 'I haul logs down this road every day. A battle\'s a nice short break.', lose: 'Dropped the load. Well fought.' } },
  { id: 'r111-perry', x: 537, y: 697, sprite: 'npc1-headband-boy', face: 4, move: 'still', lines: ['Check the log stacks. There\'s always something clinging on. Usually Pineco. Once, my hat.'],
    trainer: { cls: 'Bug Catcher', name: 'Perry', avatar: 'bugcatcher', sight: 5, money: 16, team: [['sewaddle',0],['pineco',1],['sewaddle',1],['joltik',2],['pineco',2],['sewaddle',3]], say: 'Pineco hang off the log stacks along the landings. Battle?', lose: 'My Pineco came off the stack!' } },
  { id: 'r111-moss', x: 544, y: 692, sprite: 'fishing', face: 0, move: 'still', lines: ['The trucks don\'t scare the fish. Nothing scares the fish. Believe me, I\'ve tried.'],
    trainer: { cls: 'Fisherman', name: 'Moss', avatar: 'fisherman', sight: 5, money: 20, team: [['magikarp',0],['krabby',1],['magikarp',1],['chinchou',2],['krabby',2],['squirtle',3]], say: 'I fish beside the haul road. Care to try your luck on me?', lose: 'Nothing biting today, not even you.' } },
  { id: 'r111-quill', x: 556, y: 698, sprite: 'npc1-explorer', face: 4, move: 'still', lines: ['Pinegrove timber ends up all over Kenora. Every plank of it starts on this road.'],
    trainer: { cls: 'Hiker', name: 'Quill', avatar: 'hiker', sight: 5, money: 24, team: [['timburr',0],['purrloin',1],['timburr',1],['slowpoke',2],['purrloin',2],['timburr',3]], say: 'The haul road\'s a long walk. A battle makes it shorter!', lose: 'You wore me down.' } },
  // ---------- Spindlewood: the timber dock (quay, crane, log yards and the cove; people tell what an ordinary visitor sees, nothing about the boats' real business) ----------
  { id: 't6-crane', x: 611, y: 682, sprite: 'npc2-jumpsuit-man', face: 0, move: 'still', lines: ['That crane lifts a whole stack in one go. It\'s hardly stopped since dawn.', 'Mind your head. The driver hasn\'t looked down once in thirty years.'] },
  { id: 't6-tally', x: 603, y: 679, sprite: 'npc2-striped-shirt-man', face: 2, move: 'still', lines: ['Every load on or off this quay gets tallied. A busy day is a long day.', 'Funny thing. One boat goes out after dark and never gets tallied. Not my boat, not my business.'] },
  { id: 't6-sawdust', x: 598, y: 679, sprite: 'npc2-pink-suit-man', face: 0, move: 'wander', r: 1, lines: ['Sawdust and salt. You stop smelling either after the first week.'] },
  { id: 't6-rot', x: 589, y: 676, sprite: 'npc3-old-man-cane', face: 0, move: 'still', lines: ['Rot is the enemy. One damp log and the buyers send the whole load back.'] },
  { id: 't6-pinegrove', x: 595, y: 674, sprite: 'delivery', face: 6, move: 'wander', r: 1, lines: ['Every log on this quay came down Route 111 stamped with the Pinegrove mark.', 'Route 111 is the west road out of town. Follow the log trucks and you\'ll reach Pinegrove.'] },
  { id: 't6-fungus', x: 579, y: 676, sprite: 'npc1-blue-haired-boy', face: 0, move: 'wander', r: 2, lines: ['Some folk think we\'re the fungus town. We\'re not. We just have a lot of boats.', 'The fungus town is Sporehaven, south of Pinegrove. Easy mistake. Well, no, it isn\'t.'] },
  { id: 't6-gull', x: 599, y: 675, sprite: 'npc4-ponytail-girl', face: 2, move: 'wander', r: 1, lines: ['Wingull sit on every post and steal lunch. Hold on to your sandwich!', 'There used to be more of them, mind. Gulls don\'t usually get picky about a quay.'] },
  { id: 't6-wimpod', x: 611, y: 677, sprite: 'npc2-yellow-shirt-boy', face: 0, move: 'wander', r: 1, lines: ['Wimpod scuttle about under the boards. Drop a crumb and they all come out to look.'] },
  { id: 't6-night', x: 603, y: 687, sprite: 'npc3-old-woman-cane', face: 2, move: 'still', lines: ['At night a big Golisopod walks right out onto the wharf. We just step round it.', 'The wharf is never empty after dark. Boats, crates, Golisopod. Busiest dark you\'ll ever see.'] },
  { id: 't6-craft', x: 624, y: 682, sprite: 'npc4-sailor', face: 2, move: 'still', lines: ['Boats in and out all day. A cove this size fills up fast.'] },
  { id: 't6-cove', x: 607, y: 687, sprite: 'npc4-sailor', face: 0, move: 'still', lines: ['Tentacool drift into the cove on the tide. At night Chinchou glow under the boards.'] },
  { id: 't6-yard', x: 599, y: 690, sprite: 'npc2-pink-suit-man', face: 0, move: 'still', lines: ['Pineco hang off the log stacks and Nickit nick tools. Count your gear at the end of the day.'] },
  // ---------- Sporehaven: villagers (a settlement that keeps its lamps low and lets the forest outshine it; caretakers, not cultists; nothing here is story-gated) ----------
  { id: 'g8-lamps', x: 501, y: 807, sprite: 'npc3-old-woman-cane', face: 0, move: 'still', lines: ['We keep our lamps low here. The forest does the shining, and it does it better.', 'Route 1 runs west to the Quiet Plain. My mother walked it every year with flowers.'] },
  { id: 'g8-warden', x: 509, y: 805, sprite: 'npc1-green-shirt-man', face: 6, move: 'still', lines: ['A warden clears, treats and patrols. Nobody thanks us for it, and we do it anyway.'] },
  { id: 'g8-line', x: 497, y: 805, sprite: 'npc2-bearded-man', face: 0, move: 'still', lines: ['The east road runs to Duskmoss. We cut the fungus back along it and put up no sign.', 'Why? Because we always have. My grandmother cut it, and hers did before her.'] },
  { id: 'g8-night', x: 517, y: 790, sprite: 'npc2-red-jacket-woman', face: 0, move: 'wander', r: 2, lines: ['Walk out at night. The wood is the lit thing and the town is the dark one. We like it so.'] },
  { id: 'g8-kid', x: 486, y: 790, sprite: 'npc4-brown-haired-boy', face: 0, move: 'wander', r: 2, lines: ['That big cap is the gym. Rue runs it herself. Her Breloom is the one everybody remembers.', 'Bring something that flies or something that burns. And something that can take a punch!'] },
  { id: 'g8-foongus', x: 503, y: 795, sprite: 'npc4-blonde-girl', face: 0, move: 'wander', r: 1, lines: ['See a Poke Ball on the path? Look twice. Some are Foongus. The forest does its own defending.'] },
  { id: 'g8-forager', x: 483, y: 810, sprite: 'npc1-ponytail-girl', face: 0, move: 'wander', r: 2, lines: ['Morelull glow at the edge of every clearing. We leave them be, and they leave us be.', 'Route 2, north of town, is thick with them. Foongus and Wooper too, if you want a catch.'] },
  { id: 'g8-pools', x: 523, y: 810, sprite: 'fishing', face: 0, move: 'wander', r: 1, lines: ['There is standing water between the caps all the way down Route 2. Wooper love it.'] },
  { id: 'g8-spindle', x: 525, y: 805, sprite: 'npc1-red-cap-man', face: 4, move: 'still', lines: ['Spindlewood is not the fungus town. We are. They just have the boats.'] },
  { id: 'g8-route2', x: 473, y: 805, sprite: 'npc5-old-man', face: 0, move: 'still', lines: ['Route 2 starts the moment you leave town. You are in the forest the whole way to Pinegrove.'] },
  { id: 'g8-dusk', x: 533, y: 805, sprite: 'npc4-sailor', face: 0, move: 'still', lines: ['Our crews go down to Duskmoss to hold the line. They are welcome there, and always have been.'] },
  { id: 'g8-drift', x: 494, y: 790, sprite: 'npc3-apron-woman', face: 0, move: 'wander', r: 2, lines: ['Spores drift. The line holds, but not perfectly. If something glows, word goes up the road.', 'My gran had a saying about the glow climbing. I forget how it ends. Something about the dark.'] },

  // ---------- Route 2: the mushroom route (the fungal forest the whole way; damp ground, standing water between the caps, nothing hunts and everything waits) ----------
  { id: 'r2-wynne', x: 455, y: 753, sprite: 'npc2-pink-top-girl', face: 0, move: 'still', lines: ['The ground is soft and damp out here. It grows everything, including my collection.'],
    trainer: { cls: 'Forager', name: 'Wynne', avatar: 'picnicker', sight: 5, money: 24, team: [['foongus',0],['morelull',1],['wooper',1],['foongus',2],['morelull',2],['tangela',3]], say: 'Nothing on this road hunts. Everything waits. So do I, for a challenger!', lose: 'You were worth the wait.' } },
  { id: 'r2-bram', x: 456, y: 753, sprite: 'fishing2', face: 0, move: 'still', lines: ['Water pools between the caps all the way down this road. The Wooper think it\'s paradise.'],
    trainer: { cls: 'Fisherman', name: 'Bram', avatar: 'fisherman', sight: 5, money: 20, team: [['wooper',0],['wooper',1],['foongus',1],['wooper',2],['tangela',2],['wooper',3]], say: 'Wooper live in the standing water. So do my best catches!', lose: 'My line was never going to hold.' } },
  { id: 'r2-orlo', x: 456, y: 752, sprite: 'npc1-explorer', face: 0, move: 'still', lines: ['It glows brighter out here at night than the town ever does. Shiinotic, mostly.'],
    trainer: { cls: 'Hiker', name: 'Orlo', avatar: 'hiker', sight: 5, money: 24, team: [['tangela',0],['foongus',1],['morelull',1],['tangela',2],['wooper',2],['foongus',3]], say: 'I\'ve walked this road a hundred times and it still glows new. Battle?', lose: 'A hundred walks didn\'t prepare me for you.' } },
  { id: 'r2-pip', x: 487, y: 738, sprite: 'npc4-vest-boy', face: 0, move: 'still', lines: ['Nothing on the fungal floor chases you. It just waits. Which is somehow worse.'],
    trainer: { cls: 'Bug Catcher', name: 'Pip', avatar: 'bugcatcher', sight: 5, money: 16, team: [['morelull',0],['foongus',1],['morelull',1],['foongus',2],['morelull',2],['foongus',3]], say: 'Foongus and Morelull live under the caps. Want to meet them?', lose: 'My mushrooms wilted!' } },

  // ---------- Route 101: the quarantine line (the crews' road; the fungus is cut back along it, thinning toward Duskmoss; it is maintained and not advertised) ----------
  { id: 'r101-sedge', x: 562, y: 804, sprite: 'npc3-bearded-man', face: 0, move: 'still', lines: ['Cut it back, treat the stumps, move on. That is the whole job.'],
    trainer: { cls: 'Warden', name: 'Sedge', avatar: 'hiker', sight: 5, money: 24, team: [['stunky',0],['shroomish',1],['croagunk',1],['toedscool',2],['stunky',2],['shroomish',3]], say: 'We cut the fungus back along this road every week. You are in my section!', lose: 'Clean cut. Well done.' } },
  { id: 'r101-tamsin', x: 567, y: 806, sprite: 'npc1-explorer', face: 4, move: 'still', lines: ['The glow thins out toward Duskmoss because we make it. Not because it wants to.'],
    trainer: { cls: 'Warden', name: 'Tamsin', avatar: 'backpacker', sight: 5, money: 24, team: [['croagunk',0],['stunky',1],['shroomish',1],['croagunk',2],['toedscool',2],['stunky',3]], say: 'I patrol this stretch daily. Nothing gets by me. Not even a trainer!', lose: 'I could not hold the line against you.' } },
  { id: 'r101-flint', x: 567, y: 800, sprite: 'npc1-explorer', face: 0, move: 'still', lines: ['Nobody puts up signs for this road. It does not need advertising.'],
    trainer: { cls: 'Hiker', name: 'Flint', avatar: 'hiker', sight: 5, money: 24, team: [['stunky',0],['croagunk',1],['stunky',1],['shroomish',2],['toedscool',2],['croagunk',3]], say: 'Long road, quiet crews. A battle breaks it up nicely.', lose: 'You wore me out.' } },
  { id: 'r101-ivo', x: 567, y: 807, sprite: 'doctor', face: 4, move: 'still', lines: ['By Duskmoss there is hardly any glow left. That is the point.'],
    trainer: { cls: 'Scientist', name: 'Ivo', avatar: 'scientist', sight: 5, money: 24, team: [['shroomish',0],['toedscool',1],['stunky',1],['croagunk',2],['shroomish',2],['toedscool',3]], say: 'I treat the cut ends so nothing regrows. Mind the slippery bits!', lose: 'Well. That was an unexpected result. I\'ll write it up.' } },

  // ---------- Duskmoss: villagers (the town at the end of the road; Sporehaven keeps the line, the town knows what it owes them; the sea side is ordinary; nothing here is story-gated) ----------
  { id: 't8-glow', x: 613, y: 821, sprite: 'npc3-old-man-orange', face: 0, move: 'still', lines: ['At night there is a wall of soft light where the forest starts. We are the dark part.'] },
  { id: 't8-warden', x: 617, y: 831, sprite: 'npc1-green-shirt-man', face: 6, move: 'still', lines: ['Sporehaven crews cut and treat the line all week. Duskmoss has always been glad to see us.'] },
  { id: 't8-treat', x: 612, y: 817, sprite: 'npc2-jumpsuit-man', face: 6, move: 'still', lines: ['Cut it back, treat the stumps, move on. The line holds, but not perfectly.'] },
  { id: 't8-kid', x: 603, y: 835, sprite: 'npc4-brown-haired-boy', face: 0, move: 'wander', r: 2, lines: ['Something on our fence started glowing last week. Mum sent word up the road.', 'Then a nice lady with a clipboard came and measured it. She said it was a very good glow.'] },
  { id: 't8-gran', x: 594, y: 836, sprite: 'npc3-old-woman-cane', face: 0, move: 'still', lines: ['I stopped seeing the glow years ago. I only look when someone new asks about it.'] },
  { id: 't8-sea', x: 632, y: 838, sprite: 'fishing', face: 0, move: 'wander', r: 1, lines: ['The sea here is just the sea. After a day facing the other side, I like that.'] },
  { id: 't8-sailor', x: 630, y: 836, sprite: 'npc4-sailor', face: 0, move: 'still', lines: ['Wingull and Mareanie on the shore, Shellos in the shallows. Nothing strange comes out of the water.'] },
  { id: 't8-spore', x: 610, y: 839, sprite: 'npc2-purple-top-woman', face: 2, move: 'wander', r: 1, lines: ['See that mushroom in the square? It was not there last week. We are keeping an eye on it.', 'I think it is keeping an eye on us, too.'] },
  { id: 't8-goomy', x: 600, y: 837, sprite: 'npc1-ponytail-girl', face: 0, move: 'wander', r: 2, lines: ['Goomy like the damp ground by the line. Tympole too. Mind the slippery bits.', 'Mostly the slippery bits are Goomy.'] },
  { id: 't8-quiet', x: 636, y: 836, sprite: 'npc2-yellow-suit-man', face: 4, move: 'still', lines: ['A quiet end of the road. People call that dull. I call it a place that is still here.', 'Route 101 goes back to Sporehaven. Route 103 follows the black shore, and nobody follows that.'] },
  { id: 't8-night', x: 606, y: 846, sprite: 'npc5-old-man', face: 0, move: 'still', lines: ['Duskull drift through after dark and Litwick light up the lanes. They mean no harm.'] },
  { id: 't8-boats', x: 625, y: 837, sprite: 'npc3-apron-woman', face: 0, move: 'wander', r: 1, lines: ['Boats go out at dawn and come back by noon. Half the town eats what they bring in.'] },

  // ---------- Route 103: the black shore (dark sand and sea cliffs running west along the bottom edge; the least travelled coast, nothing is out here and nothing comes) ----------
  { id: 'r103-orm', x: 586, y: 888, sprite: 'fishing', face: 2, move: 'still', lines: ['Nothing bites out here that anyone wants to talk about. Suits me.'],
    trainer: { cls: 'Fisherman', name: 'Orm', avatar: 'fisherman', sight: 5, money: 20, team: [['finneon',0],['magikarp',1],['staryu',1],['chinchou',2],['krabby',2],['finneon',3]], say: 'Quiet shore, quiet fish, and then you turn up. Battle?', lose: 'The tide\'s turned on me.' } },
  { id: 'r103-hale', x: 583, y: 903, sprite: 'npc4-sailor', face: 6, move: 'still', lines: ['Dark sand all the way west. The least travelled coast in Kenora.'],
    trainer: { cls: 'Sailor', name: 'Hale', avatar: 'sailor', sight: 5, money: 24, team: [['staryu',0],['finneon',1],['krabby',1],['staryu',2],['chinchou',2],['krabby',3]], say: 'Nobody sails past here. You\'re the first face I\'ve seen all week!', lose: 'Well sailed. I mean, well battled.' } },
  { id: 'r103-nell', x: 514, y: 902, sprite: 'npc4-ponytail-girl', face: 0, move: 'still', lines: ['The cliffs above the beach hold nothing. I checked. Twice.'],
    trainer: { cls: 'Lass', name: 'Nell', avatar: 'lass', sight: 5, money: 24, team: [['finneon',0],['greavard',1],['staryu',1],['finneon',2],['greavard',2],['dreepy',3]], say: 'Nothing\'s out here and nothing comes. Except you!', lose: 'Well, that was something at last.' } },
  { id: 'r103-brin', x: 548, y: 902, sprite: 'npc1-explorer', face: 0, move: 'still', lines: ['Greavard follow you along the sand at night. They never come close. They just want company.'],
    trainer: { cls: 'Backpacker', name: 'Brin', avatar: 'backpacker', sight: 5, money: 24, team: [['greavard',0],['finneon',1],['greavard',1],['dreepy',2],['staryu',2],['greavard',3]], say: 'It gets lonely on this coast. A battle is company!', lose: 'Thank you for the company.' } },
  // ---------- Route 1: the road south to Quiet Plain (an old paved road, cracked end to end with the grass forced up through it; nobody walks it, one person keeps its waymarker stones legible from the far end; the strays that follow you south; no birds) ----------
  { id: 'r1-stone9', x: 422, y: 805, sprite: null, face: 0, move: 'still', name: 'Waymarker', lines: ['A waymarker stone, cut with a 9. The edges are sharp.','Someone keeps these legible. The chips at the foot are still pale.'] },
  { id: 'r1-stone8', x: 412, y: 807, sprite: null, face: 0, move: 'still', name: 'Waymarker', lines: ['A waymarker stone, cut with an 8. No moss on it at all.','Everything else on this road is going green, but not the numerals.'] },
  { id: 'r1-stone7', x: 416, y: 819, sprite: null, face: 0, move: 'still', name: 'Waymarker', lines: ['A waymarker stone, cut with a 7. The cut is deep and clean.','The road is cracked end to end. The stones are not.'] },
  { id: 'r1-stone6', x: 425, y: 825, sprite: null, face: 0, move: 'still', name: 'Waymarker', lines: ['A waymarker stone, cut with a 6. The chips are pale.','Whoever cuts these has been along this road more than once.'] },
  { id: 'r1-stone5', x: 431, y: 830, sprite: null, face: 0, move: 'still', name: 'Waymarker', lines: ['A waymarker stone, cut with a 5. Halfway, near enough.','The numerals are the only thing on this road anyone looks after.'] },
  { id: 'r1-stone4', x: 425, y: 838, sprite: null, face: 0, move: 'still', name: 'Waymarker', lines: ['A waymarker stone, cut with a 4. The edges are crisp.','It counts down, one stone at a time, toward the south.'] },
  { id: 'r1-stone3', x: 413, y: 842, sprite: null, face: 0, move: 'still', name: 'Waymarker', lines: ['A waymarker stone, cut with a 3. Fresh pale chips lie at its foot.','Nobody walks this road, but someone keeps the numbers right.'] },
  { id: 'r1-stone2', x: 410, y: 847, sprite: null, face: 0, move: 'still', name: 'Waymarker', lines: ['A waymarker stone, cut with a 2. The edges are sharp.','You can see the open plain from here.'] },
  { id: 'r1-stone1', x: 398, y: 851, sprite: null, face: 0, move: 'still', name: 'Waymarker', lines: ['A waymarker stone, cut with a 1. The edges are sharp.','The last one. Whoever cuts these is not far off.'] },
  { id: 'r1-wick', x: 419, y: 804, sprite: 'npc2-red-shirt-boy', face: 2, move: 'still', lines: ['The strays on this road walk south with you. They never walk back.'],
    trainer: { cls: 'Youngster', name: 'Wick', avatar: 'youngster', sight: 5, money: 16, team: [['rattata', 0], ['lillipup', 1], ['rattata', 1], ['lillipup', 2], ['nickit', 2], ['lillipup', 3]], say: 'Mind the cracks. Half this road is held together by weeds!', lose: 'The weeds held up better than I did.' } },
  { id: 'r1-edie', x: 421, y: 816, sprite: 'npc1-ponytail-girl', face: 6, move: 'still', lines: ['No birds out here. Nothing ever perches on this road.'],
    trainer: { cls: 'Lass', name: 'Edie', avatar: 'lass', sight: 5, money: 24, team: [['oddish', 0], ['oddish', 1], ['gastly', 1], ['oddish', 2], ['gastly', 2], ['duskull', 3]], say: 'It is very quiet on this road. Shall we change that?', lose: 'Quiet again. I should not have spoken.' } },
  { id: 'r1-corwin', x: 415, y: 834, sprite: 'npc1-explorer', face: 2, move: 'still', lines: ['Somebody built this road to last. Then they stopped coming.'],
    trainer: { cls: 'Hiker', name: 'Corwin', avatar: 'hiker', sight: 5, money: 24, team: [['nickit', 0], ['lillipup', 1], ['nickit', 1], ['rattata', 2], ['lillipup', 2], ['nickit', 3]], say: 'I walk it end to end every year. The weeds win a little more each time.', lose: 'The weeds always win. So do you.' } },
  { id: 'r1-mabel', x: 391, y: 862, sprite: 'npc4-blonde-girl', face: 6, move: 'still', lines: ['The strays walk you down to the end. Something else waits there.'],
    trainer: { cls: 'Picnicker', name: 'Mabel', avatar: 'picnicker', sight: 5, money: 24, team: [['lillipup', 0], ['lillipup', 1], ['duskull', 1], ['nickit', 2], ['gastly', 2], ['lillipup', 3]], say: 'The strays brought me this far. Want to see what they taught me?', lose: 'Even the strays are impressed.' } },

  // ---------- Quiet Plain: the memorial (open grass, markers, a great deal of wind; nobody guards it and nothing gates it; the ghost-speaker teaches Sensing Shadow Pokemon to anyone who walks down, and their name is still open) ----------
  { id: 'l4-speaker', x: 391, y: 885, sprite: 'npc1-robed-woman', face: 6, move: 'still', script: 'teach', skill: 'sense', name: 'Ghost-speaker', lines: ['You walked all the way down. That is all this place has ever asked of anyone.', 'The dead here remember how that darkness felt. They taught me to spot it. I was not there. Listen?'], known: ['The Curse has come before. This plain is what the region built after, and it has stayed open.', 'I was not there. I only repeat what the dead tell me, and they do not always keep to the order.'] },
  { id: 'l4-wind', x: 384, y: 883, sprite: 'npc5-old-man', face: 0, move: 'still', lines: ['There is always wind out here. You stop hearing it after a while.', 'Whoever cuts the road stones works alone out here. I have never seen them take a rest.'] },
  { id: 'l4-flowers', x: 397, y: 893, sprite: 'npc3-old-woman-cane', face: 6, move: 'still', lines: ['I bring flowers every year. My mother did, and hers. Nobody ever told me who they are for.'] },
  { id: 'l4-count', x: 384, y: 896, sprite: 'npc2-green-shirt-kid', face: 0, move: 'still', lines: ['Dad says it is just a nice walk. I counted the stones and got a different number twice.'] },
  { id: 'l4-habit', x: 389, y: 894, sprite: 'npc3-bearded-man', face: 0, move: 'wander', r: 1, lines: ['Most of us could not tell you what the markers are for.', 'We come anyway. The habit outlived the reason.'] },
];
